code.source:
#include <iostream>
using namespace std;

int main() {
    for (int i = 10; i <= 30; i++) {
        if (i % 7 == 0) {
            cout << "Found " << i << endl;
            break;
        }
    }
    cout << "Done" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 5; i++) {
        if (i == 3) {
            continue;
        }
        cout << i << " ";
    }
    cout << endl;
    return 0;
}

